-- 0005 surveys: survey header table (title, intro, target responses, status, version, fingerprint).
-- Generated by drizzle-kit from src/db/schema.ts, then hand-edited:
--   [hand-edit 1] survey_questions.survey_id is added NULLABLE, existing questions are backfilled into
--                 one v1 DRAFT header per (organization, event, audience), then it is made NOT NULL.
--                 Backfilled headers are human-owned (is_ai_generated = false, no fingerprint), so the
--                 AI never overwrites them. No question row is deleted or changed except survey_id.
--   [hand-edit 2] REVOKE client write privileges on surveys (server-only writes, like survey_questions).
-- Do not use drizzle-kit push against a database with data: the backfill only runs through migrate.
CREATE TYPE "public"."survey_status" AS ENUM('DRAFT', 'OPEN', 'CLOSED');--> statement-breakpoint
CREATE TABLE "surveys" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"organization_id" uuid NOT NULL,
	"event_id" uuid NOT NULL,
	"audience" "survey_audience" NOT NULL,
	"version" integer DEFAULT 1 NOT NULL,
	"status" "survey_status" DEFAULT 'DRAFT' NOT NULL,
	"title" text NOT NULL,
	"intro" text,
	"target_responses" integer,
	"is_ai_generated" boolean DEFAULT false NOT NULL,
	"blueprint_key" text,
	"ai_fingerprint" char(64),
	"opens_at" timestamp with time zone,
	"closes_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "surveys_event_audience_version_uq" UNIQUE("event_id","audience","version"),
	CONSTRAINT "surveys_id_scope_uq" UNIQUE("id","organization_id","event_id","audience"),
	CONSTRAINT "surveys_title_not_blank" CHECK (length(trim("surveys"."title")) > 0),
	CONSTRAINT "surveys_version_positive" CHECK ("surveys"."version" >= 1),
	CONSTRAINT "surveys_target_responses_positive" CHECK ("surveys"."target_responses" is null or "surveys"."target_responses" > 0),
	CONSTRAINT "surveys_blueprint_key_only_for_ai" CHECK ("surveys"."blueprint_key" is null or "surveys"."is_ai_generated"),
	CONSTRAINT "surveys_blueprint_key_format" CHECK ("surveys"."blueprint_key" is null or "surveys"."blueprint_key" ~ '^survey_[a-z_]{1,40}$'),
	CONSTRAINT "surveys_ai_fingerprint_only_for_ai" CHECK ("surveys"."ai_fingerprint" is null or "surveys"."is_ai_generated"),
	CONSTRAINT "surveys_ai_fingerprint_hex" CHECK ("surveys"."ai_fingerprint" is null or "surveys"."ai_fingerprint" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "surveys_window_ordered" CHECK ("surveys"."closes_at" is null or "surveys"."opens_at" is null or "surveys"."closes_at" > "surveys"."opens_at")
);
--> statement-breakpoint
ALTER TABLE "surveys" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
