-- [hand-edit 1] backfill: one header per existing (organization, event, audience)
INSERT INTO "surveys" ("organization_id", "event_id", "audience", "version", "status", "title", "is_ai_generated")
SELECT DISTINCT "organization_id", "event_id", "audience", 1, 'DRAFT'::"survey_status", 'Anket', false
FROM "survey_questions";--> statement-breakpoint
UPDATE "survey_questions" q SET "survey_id" = s."id"
FROM "surveys" s
WHERE s."organization_id" = q."organization_id" AND s."event_id" = q."event_id" AND s."audience" = q."audience" AND s."version" = 1;--> statement-breakpoint
